CREATE TABLE IF NOT EXISTS admin_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id VARCHAR(191) NOT NULL, action VARCHAR(191) NOT NULL, settings_revision INT NOT NULL, created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS site_settings (id INT PRIMARY KEY, value_json LONGTEXT NOT NULL, revision INT NOT NULL, updated_at VARCHAR(40) NOT NULL, updated_by VARCHAR(191) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_publication (id INT PRIMARY KEY, object_key VARCHAR(191) NOT NULL, observed_at VARCHAR(40) NOT NULL, count INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_sync_runs (day VARCHAR(16) PRIMARY KEY, run_id VARCHAR(191) NOT NULL UNIQUE, status VARCHAR(32) NOT NULL, state_json LONGTEXT NOT NULL, lease_until BIGINT NOT NULL DEFAULT 0, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS source_detail_runs (run_id VARCHAR(191) PRIMARY KEY, base_key VARCHAR(191) NOT NULL UNIQUE, status VARCHAR(32) NOT NULL, state_json LONGTEXT NOT NULL, lease_until BIGINT NOT NULL DEFAULT 0, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS market_listings (id VARCHAR(191) PRIMARY KEY, owner_id VARCHAR(191) NOT NULL, data_json LONGTEXT NOT NULL, status VARCHAR(32) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, promoted_until BIGINT NOT NULL DEFAULT 0, INDEX market_owner(owner_id), INDEX market_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS market_uploads (path VARCHAR(191) PRIMARY KEY, owner_id VARCHAR(191) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS promotion_orders (id VARCHAR(191) PRIMARY KEY, listing_id VARCHAR(191) NOT NULL, owner_id VARCHAR(191) NOT NULL, client_key VARCHAR(191) NOT NULL UNIQUE, active_slot VARCHAR(191) UNIQUE, plan_id VARCHAR(191) NOT NULL, plan_label VARCHAR(191) NOT NULL, days INT NOT NULL, amount BIGINT NOT NULL, status VARCHAR(32) NOT NULL, callback_hash CHAR(64) NOT NULL, invoice_id VARCHAR(191) UNIQUE, qr_json LONGTEXT, created_at BIGINT NOT NULL, paid_at BIGINT, check_lease_until BIGINT NOT NULL DEFAULT 0, last_checked_at BIGINT NOT NULL DEFAULT 0, payment_ids_json LONGTEXT, error_code VARCHAR(191), INDEX payment_owner(owner_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS stored_objects (key_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY, object_key VARCHAR(1000) NOT NULL, body MEDIUMBLOB NOT NULL, metadata_json TEXT NOT NULL, expires_at BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS auth_users (id VARCHAR(191) PRIMARY KEY, email VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'user', created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY, user_id VARCHAR(191) NOT NULL, expires_at BIGINT NOT NULL, INDEX session_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS auth_limits (key_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY, attempts INT NOT NULL, reset_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
